  /**
   * Method under test:
   * {@link GrpcAPI.AccountResourceMessage#parseFrom(InputStream)}
   */
  @Test
  public void testAccountResourceMessageParseFrom2() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));

    // Act and Assert
    assertThrows(IOException.class, () -> GrpcAPI.AccountResourceMessage.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

