  /**
   * Method under test: {@link GrpcAPI.BlockLimit#parseFrom(InputStream)}
   */
  @Test
  public void testBlockLimitParseFrom6() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));

    // Act and Assert
    assertThrows(IOException.class, () -> GrpcAPI.BlockLimit.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

