  /**
   * Method under test:
   * {@link GrpcAPI.CanDelegatedMaxSizeResponseMessage#parseDelimitedFrom(InputStream)}
   */
  @Test
  public void testCanDelegatedMaxSizeResponseMessageParseDelimitedFrom3() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));
    when(input.read()).thenReturn(1);

    // Act and Assert
    assertThrows(IOException.class, () -> GrpcAPI.CanDelegatedMaxSizeResponseMessage.parseDelimitedFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(1));
    verify(input).read();
  }

