  /**
   * Method under test: {@link GrpcAPI.EmptyMessage#parseFrom(InputStream)}
   */
  @Test
  public void testEmptyMessageParseFrom6() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));

    // Act and Assert
    assertThrows(IOException.class, () -> GrpcAPI.EmptyMessage.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

  /**
   * Method under test: {@link GrpcAPI.EmptyMessage#parseFrom(InputStream)}
   */
  @Test
  public void testEmptyMessageParseFrom7() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt()))
        .thenThrow(new InvalidProtocolBufferException("The characteristics of someone or something"));

    // Act and Assert
    assertThrows(InvalidProtocolBufferException.class, () -> GrpcAPI.EmptyMessage.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

