  /**
   * Method under test:
   * {@link GrpcAPI.PaginatedMessage#parseDelimitedFrom(InputStream, ExtensionRegistryLite)}
   */
  @Test
  public void testPaginatedMessageParseDelimitedFrom6() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{});

    // Act and Assert
    assertNull(GrpcAPI.PaginatedMessage.parseDelimitedFrom(input, ExtensionRegistryLite.getEmptyRegistry()));
    assertEquals(-1, input.read(new byte[]{}));
  }

  /**
   * Method under test:
   * {@link GrpcAPI.PaginatedMessage#parseDelimitedFrom(InputStream, ExtensionRegistryLite)}
   */
  @Test
  public void testPaginatedMessageParseDelimitedFrom7() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));
    when(input.read()).thenReturn(1);

    // Act and Assert
    assertThrows(IOException.class,
        () -> GrpcAPI.PaginatedMessage.parseDelimitedFrom(input, ExtensionRegistryLite.getEmptyRegistry()));
    verify(input).read(isA(byte[].class), eq(0), eq(1));
    verify(input).read();
  }

  /**
   * Method under test:
   * {@link GrpcAPI.PaginatedMessage#parseDelimitedFrom(InputStream, ExtensionRegistryLite)}
   */
  @Test
  public void testPaginatedMessageParseDelimitedFrom8() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt()))
        .thenThrow(new InvalidProtocolBufferException("The characteristics of someone or something"));
    when(input.read()).thenReturn(1);

    // Act and Assert
    assertThrows(InvalidProtocolBufferException.class,
        () -> GrpcAPI.PaginatedMessage.parseDelimitedFrom(input, ExtensionRegistryLite.getEmptyRegistry()));
    verify(input).read(isA(byte[].class), eq(0), eq(1));
    verify(input).read();
  }

