  @Test
  public void testPaymentAddressMessageGetPaymentAddressBytes() {
    // Arrange
    GrpcAPI.PaymentAddressMessage defaultInstance = GrpcAPI.PaymentAddressMessage.getDefaultInstance();

    // Act
    ByteString actualPaymentAddressBytes = defaultInstance.getPaymentAddressBytes();

    // Assert
    GrpcAPI.DiversifierMessage d = defaultInstance.getD();
    List<Descriptors.FieldDescriptor> fields = d.getDescriptorForType().getFields();
    assertEquals(1, fields.size());
    List<Descriptors.FieldDescriptor> fields2 = defaultInstance.getDescriptorForType().getFields();
    assertEquals(3, fields2.size());
    ByteString byteString = actualPaymentAddressBytes.EMPTY;
    assertEquals(byteString, actualPaymentAddressBytes);
    assertSame(byteString, fields.get(0).getDefaultValue());
    assertSame(byteString, fields2.get(1).getDefaultValue());
    assertSame(byteString, d.getD());
    assertSame(byteString, defaultInstance.getPkD());
  }

