  /**
   * Method under test:
   * {@link GrpcAPI.PrivateShieldedTRC20Parameters#getFromAmountBytes()}
   */
  @Test
  public void testPrivateShieldedTRC20ParametersGetFromAmountBytes() {
    // Arrange
    GrpcAPI.PrivateShieldedTRC20Parameters defaultInstance = GrpcAPI.PrivateShieldedTRC20Parameters
        .getDefaultInstance();

    // Act
    ByteString actualFromAmountBytes = defaultInstance.getFromAmountBytes();

    // Assert
    ByteString byteString = actualFromAmountBytes.EMPTY;
    assertEquals(byteString, actualFromAmountBytes);
    List<Descriptors.FieldDescriptor> fields = defaultInstance.getDescriptorForType().getFields();
    assertEquals(GrpcAPI.PrivateShieldedTRC20Parameters.SHIELDED_TRC20_CONTRACT_ADDRESS_FIELD_NUMBER, fields.size());
    assertSame(byteString, fields.get(0).getDefaultValue());
    assertSame(byteString, fields.get(1).getDefaultValue());
    assertSame(byteString, fields.get(8).getDefaultValue());
    assertSame(byteString, defaultInstance.getAsk());
    assertSame(byteString, defaultInstance.getNsk());
    assertSame(byteString, defaultInstance.getOvk());
    assertSame(byteString, defaultInstance.getShieldedTRC20ContractAddress());
    assertSame(byteString, defaultInstance.getTransparentToAddress());
  }

