  /**
   * Method under test:
   * {@link GrpcAPI.TransactionSignWeight.Result.response_code#valueOf(int)}
   */
  @Test
  public void testTransactionSignWeight_Result_response_codeValueOf() {
    // Arrange, Act and Assert
    assertNull(GrpcAPI.TransactionSignWeight.Result.response_code.valueOf(42));
    assertEquals(GrpcAPI.TransactionSignWeight.Result.response_code.ENOUGH_PERMISSION,
        GrpcAPI.TransactionSignWeight.Result.response_code.valueOf(0));
    assertEquals(GrpcAPI.TransactionSignWeight.Result.response_code.NOT_ENOUGH_PERMISSION,
        GrpcAPI.TransactionSignWeight.Result.response_code.valueOf(1));
    assertEquals(GrpcAPI.TransactionSignWeight.Result.response_code.SIGNATURE_FORMAT_ERROR,
        GrpcAPI.TransactionSignWeight.Result.response_code.valueOf(2));
    assertEquals(GrpcAPI.TransactionSignWeight.Result.response_code.COMPUTE_ADDRESS_ERROR,
        GrpcAPI.TransactionSignWeight.Result.response_code.valueOf(3));
    assertEquals(GrpcAPI.TransactionSignWeight.Result.response_code.PERMISSION_ERROR,
        GrpcAPI.TransactionSignWeight.Result.response_code.valueOf(4));
    assertEquals(GrpcAPI.TransactionSignWeight.Result.response_code.OTHER_ERROR,
        GrpcAPI.TransactionSignWeight.Result.response_code
            .valueOf(GrpcAPI.TransactionSignWeight.Result.response_code.OTHER_ERROR_VALUE));
  }

